-- Replace demo SKUs with Autodesk reseller price-list (Setembro 2026).
alter table products add column if not exists sap_name text not null default '';
alter table products add column if not exists product_line text not null default '';
alter table products add column if not exists usage_type text not null default 'Commercial';
alter table products add column if not exists license_type text not null default '';
alter table products add column if not exists contract_term text not null default '';
alter table products add column if not exists deployment text not null default '';
alter table products add column if not exists notes text not null default '';
alter table products add column if not exists source text not null default 'manual';

create table if not exists catalog_meta (
  key text primary key,
  value text not null
);

create index if not exists products_line_idx on products (product_line);
create index if not exists products_source_idx on products (source);

update purchase_order_items
  set product_id = null
where product_id in (
  select id from products where source is distinct from 'price_list'
);

delete from products where source is distinct from 'price_list';

on conflict (sku) do update set
  name = excluded.name,
  category = excluded.category,
  list_price_usd = excluded.list_price_usd,
  sap_name = excluded.sap_name,
  product_line = excluded.product_line,
  usage_type = excluded.usage_type,
  license_type = excluded.license_type,
  contract_term = excluded.contract_term,
  deployment = excluded.deployment,
  notes = excluded.notes,
  source = 'price_list',
  updated_at = now();

